import { WorldsSdk } from "jsr:@worlds/sdk@^0.9.0";
import { WazooSparqlEngine } from "jsr:@wazoo/sparql-engine@^0.4.1";
import { RdfjsQuadStore, RdfjsSearchIndex } from "jsr:@worlds/sdk@^0.9.0/rdfjs";
import { MemoryStore } from "jsr:@wazoo/sparql-engine@^0.4.1";

if (import.meta.main) {
  const store = new MemoryStore();
  const client = new WorldsSdk({
    quadStore: new RdfjsQuadStore({ store }),
    searchIndex: new RdfjsSearchIndex(store),
    sparqlEngine: new WazooSparqlEngine({ store }),
  });

  await client.import({
    source: {
      kind: "serialized",
      data:
        `<http://example.com/subject> <http://example.com/predicate> "Hello, World!" .`,
      contentType: "text/turtle",
    },
  });

  const searchResponse = await client.search({ query: "Hello" });
  console.log(JSON.stringify(searchResponse, null, 2));

  const sparqlResponse = await client.sparql({
    query: `SELECT ?s ?p ?o WHERE { ?s ?p ?o }`,
  });
  console.log(JSON.stringify(sparqlResponse, null, 2));
}
